/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('.').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'
 print('\\nFILE',f.name[:-4])
 for i,l in enumerate(lines):
  if re.match(r'--- page (\\d+) ---',l):page=re.search(r'\\d+',l).group()
  if re.search(r'governed|governing law|choice of law|laws of|law of the|construed under',l,re.I):
   print('PAGE',page, ' | '.join(lines[max(0,i-1):i+4]))
PY"

